using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpWebService.Tools;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Look up a configuration value by key name.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up (e.g. 'MaxRetries', 'Timeout')")] string key)
    {
        var config = AppConfig.All;
        return config.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Key '{key}' not found. Available keys: {string.Join(", ", config.Keys)}";
    }

    [McpServerTool, Description("List all available configuration keys.")]
    public static string ListConfigKeys()
    {
        return string.Join("\n", AppConfig.All.Keys.Order());
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpWebService.Resources;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "Application Settings",
        MimeType = "application/json"),
     Description("Full application configuration as JSON.")]
    public static string GetAllSettings()
    {
        return JsonSerializer.Serialize(AppConfig.All, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://app/version",
        Name = "App Version",
        MimeType = "text/plain"),
     Description("Current application version string.")]
    public static string GetVersion()
    {
        return AppConfig.All["Version"];
    }
}

namespace McpWebService;

/// <summary>
/// Sample in-memory configuration store exposed via MCP tools and resources.
/// </summary>
public static class AppConfig
{
    public static readonly Dictionary<string, string> All = new()
    {
        ["Version"] = "1.0.0",
        ["Environment"] = "Production",
        ["MaxRetries"] = "3",
        ["Timeout"] = "30s",
        ["LogLevel"] = "Information"
    };
}

